  "headline": "FDA's records show imipenem and cilastatin is not on the shortage list as of 2026-10-21",
  "headline_cites": ["D4"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include imipenem and cilastatin as of 2026-10-21.",
      "cites": ["D4"]
    },
    {
      "text": "Corvale East holds 66 vials of the 500 mg + 500 mg injection with 4 days of supply at current use.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale Lakeside holds 105 vials of the same presentation with 29.8 days of supply at current use.",
      "cites": ["D3"]
    },
    {
      "text": "The top-ranked option by rule is to transfer 55 vials from Corvale Lakeside to Corvale East, which would leave Lakeside with two weeks of supply and bring East to 7 days.",
      "cites": ["D5"]
    },
    {
      "text": "An alternative transfer of 166 vials from Corvale General would bring Corvale East to 14 days while keeping General above two weeks.",
      "cites": ["D6"]
    },
    {
      "text": "The product label for the NDC used at all three sites names Zambon Switzerland Ltd. in Cadempino as the manufacturing plant.",
      "cites": ["E4"]
    },
    {
      "text": "FDA's shortage list shows Merck Sharp & Dohme entries for imipenem and cilastatin products marked as to be discontinued, but those are separate NDCs from the one in use at our hospitals.",
      "cites": ["E5", "E6"]
    }
  ]
}
